import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"琵琶行","description":"","frontmatter":{"title":"琵琶行","date":"2026-11-23T00:00:00.000Z","seq":3,"categories":["美文","唐诗三百首"],"collection":"《唐诗三百首 · 七言古诗》","tags":["唐诗三百首","唐"],"poem":true,"poem_quote":false,"author":"白居易","source_book":"唐诗三百首"},"headers":[],"relativePath":"blogs/唐诗三百首·七言古诗/琵琶行.md","filePath":"blogs/唐诗三百首·七言古诗/琵琶行.md"}'),o={name:"blogs/唐诗三百首·七言古诗/琵琶行.md"};function l(c,a,n,m,z,r){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="琵琶行" tabindex="-1">琵琶行 <a class="header-anchor" href="#琵琶行" aria-label="Permalink to &quot;琵琶行&quot;">​</a></h1><p class="poem-meta">唐 · 白居易　·　七言古诗</p><div class="poem"><p class="poem-stanza">浔阳江头夜送客，枫叶荻花秋瑟瑟。</p><p class="poem-stanza">主人下马客在船，举酒欲饮无管弦。</p><p class="poem-stanza">醉不成欢惨将别，别时茫茫江浸月。</p><p class="poem-stanza">忽闻水上琵琶声，主人忘归客不发。</p><p class="poem-stanza">寻声暗问弹者谁？琵琶声停欲语迟。</p><p class="poem-stanza">移船相近邀相见，添酒回灯重开宴。</p><p class="poem-stanza">千呼万唤始出来，犹抱琵琶半遮面。</p><p class="poem-stanza">转轴拨弦三两声，未成曲调先有情。</p><p class="poem-stanza">弦弦掩抑声声思，似诉平生不得志。（不得志 一作：意）</p><p class="poem-stanza">低眉信手续续弹，说尽心中无限事。</p><p class="poem-stanza">轻拢慢捻抹复挑，初为《霓裳》后《六幺》（六幺 一作：绿腰）。</p><p class="poem-stanza">大弦嘈嘈如急雨，小弦切切如私语。</p><p class="poem-stanza">嘈嘈切切错杂弹，大珠小珠落玉盘。</p><p class="poem-stanza">间关莺语花底滑，幽咽泉流冰下难。</p><p class="poem-stanza">冰泉冷涩弦凝绝，凝绝不通声暂歇。(暂歇 一作：渐歇)</p><p class="poem-stanza">别有幽愁暗恨生，此时无声胜有声。</p><p class="poem-stanza">银瓶乍破水浆迸，铁骑突出刀枪鸣。</p><p class="poem-stanza">曲终收拨当心画，四弦一声如裂帛。</p><p class="poem-stanza">东船西舫悄无言，唯见江心秋月白。</p><p class="poem-stanza">沉吟放拨插弦中，整顿衣裳起敛容。</p><p class="poem-stanza">自言本是京城女，家在虾蟆陵下住。</p><p class="poem-stanza">十三学得琵琶成，名属教坊第一部。</p><p class="poem-stanza">曲罢曾教善才服，妆成每被秋娘妒。</p><p class="poem-stanza">五陵年少争缠头，一曲红绡不知数。</p><p class="poem-stanza">钿头银篦击节碎，血色罗裙翻酒污。(银篦 一作：云)</p><p class="poem-stanza">今年欢笑复明年，秋月春风等闲度。</p><p class="poem-stanza">弟走从军阿姨死，暮去朝来颜色故。</p><p class="poem-stanza">门前冷落鞍马稀，老大嫁作商人妇。</p><p class="poem-stanza">商人重利轻别离，前月浮梁买茶去。</p><p class="poem-stanza">去来江口守空船，绕船月明江水寒。</p><p class="poem-stanza">夜深忽梦少年事，梦啼妆泪红阑干。</p><p class="poem-stanza">我闻琵琶已叹息，又闻此语重唧唧。</p><p class="poem-stanza">同是天涯沦落人，相逢何必曾相识！</p><p class="poem-stanza">我从去年辞帝京，谪居卧病浔阳城。</p><p class="poem-stanza">浔阳地僻无音乐，终岁不闻丝竹声。</p><p class="poem-stanza">住近湓江地低湿，黄芦苦竹绕宅生。</p><p class="poem-stanza">其间旦暮闻何物？杜鹃啼血猿哀鸣。</p><p class="poem-stanza">春江花朝秋月夜，往往取酒还独倾。</p><p class="poem-stanza">岂无山歌与村笛？呕哑嘲哳难为听。</p><p class="poem-stanza">今夜闻君琵琶语，如听仙乐耳暂明。</p><p class="poem-stanza">莫辞更坐弹一曲，为君翻作《琵琶行》。</p><p class="poem-stanza">感我此言良久立，却坐促弦弦转急。</p><p class="poem-stanza">凄凄不似向前声，满座重闻皆掩泣。</p><p class="poem-stanza">座中泣下谁最多？江州司马青衫湿。</p></div>',3)])])}const d=s(o,[["render",l]]);export{i as __pageData,d as default};
